html:
{%- set v = invoice_context(doc) -%}
{%- set cur = doc.currency -%}
<style>
	.rti { font-family: Arial, Helvetica, sans-serif; font-size: 9pt; color: #000; }
	.rti table { width: 100%; border-collapse: collapse; }
	.rti .box td, .rti .box th { border: 1px solid #555; padding: 3px 5px; vertical-align: top; }
	.rti th { background: #f0f0f0; font-weight: 700; text-align: left; }
	.rti .r { text-align: right; }
	.rti .c { text-align: center; }
	.rti .muted { color: #444; font-size: 8pt; }
	.rti .title { text-align: center; font-size: 13pt; font-weight: 700; letter-spacing: 1px; margin: 4px 0 6px; }
	.rti .company-name { font-size: 15pt; font-weight: 700; }
	.rti .totals td { border: none; padding: 2px 5px; }
	.rti .grand td { font-size: 11pt; font-weight: 700; border-top: 1px solid #000; }
	.rti .serials { font-size: 7.5pt; color: #333; word-break: break-all; }
</style>
<div class="rti">
	<table><tr>
		{%- if v.company.logo %}<td style="width:22%"><img src="{{ v.company.logo }}" style="max-height:60px;max-width:100%"></td>{% endif %}
		<td>
			<div class="company-name">{{ v.company.name }}</div>
			<div class="muted">{{ v.company.address }}</div>
			<div class="muted">
				{%- if v.company.gstin and not v.company.gstin_in_address %}GSTIN: <b>{{ v.company.gstin }}</b>{% endif -%}
				{%- if v.company.phone %} &nbsp; Ph: {{ v.company.phone }}{% endif -%}
				{%- if v.company.email %} &nbsp; {{ v.company.email }}{% endif -%}
			</div>
		</td>
	</tr></table>
	<div class="title">{{ _(v.title) | upper }}</div>
	<table class="box"><tr>
		<td style="width:55%">
			<div class="muted">{{ _("Billed To") }}</div>
			<b>{{ v.customer.name }}</b>
			{%- if v.customer.mobile %}<br>{{ _("Mobile") }}: {{ v.customer.mobile }}{% endif %}
			{%- if v.customer.address %}<br><span class="muted">{{ v.customer.address }}</span>{% endif %}
			{%- if v.customer.gstin %}<br>GSTIN: <b>{{ v.customer.gstin }}</b>{% endif %}
		</td>
		<td>
			{{ _("Invoice No") }}: <b>{{ doc.name }}</b><br>
			{{ _("Date") }}: {{ frappe.utils.format_date(doc.posting_date) }} {{ v.time }}<br>
			{%- if doc.is_return and doc.return_against %}{{ _("Against") }}: {{ doc.return_against }}<br>{% endif %}
			{%- if v.customer.place_of_supply %}{{ _("Place of Supply") }}: {{ v.customer.place_of_supply }}<br>{% endif %}
			{%- if doc.po_no %}{{ _("Order Ref") }}: {{ doc.po_no }}{% endif %}
		</td>
	</tr></table>
	<table class="box" style="margin-top:6px">
		<thead><tr>
			<th class="c" style="width:4%">#</th>
			<th>{{ _("Item") }}</th>
			<th style="width:10%">{{ _("HSN") }}</th>
			<th class="r" style="width:8%">{{ _("Qty") }}</th>
			<th class="r" style="width:11%">{{ _("Rate") }}</th>
			<th class="r" style="width:10%">{{ _("Discount") }}</th>
			<th class="r" style="width:13%">{{ _("Taxable Value") }}</th>
		</tr></thead>
		<tbody>
		{%- for i in v.lines %}
		<tr>
			<td class="c">{{ i.idx }}</td>
			<td><b>{{ i.item_name }}</b>{% if i.details %} <span class="muted">({{ i.details }})</span>{% endif %}
				{%- if i.show_code %}<div class="muted">{{ i.item_code }}</div>{% endif %}
				{%- if i.serials %}<div class="serials">{{ _("S/N") }}: {{ i.serials | join(", ") }}</div>{% endif %}</td>
			<td>{{ i.hsn }}</td>
			<td class="r">{{ frappe.utils.fmt_money(i.qty, precision=0) if i.qty == i.qty|int else i.qty }} {{ i.uom }}</td>
			<td class="r">{{ frappe.utils.fmt_money(i.rate, currency=cur) }}</td>
			<td class="r">{{ frappe.utils.fmt_money(i.discount, currency=cur) if i.discount else "" }}</td>
			<td class="r">{{ frappe.utils.fmt_money(i.taxable, currency=cur) }}</td>
		</tr>
		{%- endfor %}
		<tr><th colspan="3" class="r">{{ _("Total") }}</th><th class="r">{{ v.total_qty | int if v.total_qty == v.total_qty|int else v.total_qty }}</th><th></th><th></th>
			<th class="r">{{ frappe.utils.fmt_money(v.net_total, currency=cur) }}</th></tr>
		</tbody>
	</table>
	<table style="margin-top:6px"><tr>
		<td style="width:58%;vertical-align:top;padding-right:8px">
			{%- if v.hsn.kinds %}
			<table class="box">
				<thead><tr><th>{{ _("HSN") }}</th><th class="r">{{ _("Taxable") }}</th>
					{%- for k in v.hsn.kinds %}<th class="r">{{ k }}</th>{% endfor %}<th class="r">{{ _("Tax") }}</th></tr></thead>
				<tbody>
				{%- for h in v.hsn.rows %}
				<tr><td>{{ h.hsn or "-" }}</td><td class="r">{{ frappe.utils.fmt_money(h.taxable, currency=cur) }}</td>
					{%- for k in v.hsn.kinds %}{% set t = h.taxes.get(k) %}
					<td class="r">{% if t %}{{ frappe.utils.fmt_money(t.amount, currency=cur) }}<br><span class="muted">@{{ t.rate | round(2) }}%</span>{% else %}-{% endif %}</td>
					{%- endfor %}
					<td class="r">{{ frappe.utils.fmt_money(h.total_tax, currency=cur) }}</td></tr>
				{%- endfor %}
				</tbody>
			</table>
			{%- if v.tax_inclusive %}<div class="muted">{{ _("Prices include GST.") }}</div>{% endif %}
			{%- endif %}
			<div style="margin-top:6px"><span class="muted">{{ _("Amount in words") }}:</span> <b>{{ v.in_words }}</b></div>
			{%- if v.payments %}<div style="margin-top:4px" class="muted">{{ _("Paid") }}:
				{% for p in v.payments %}{{ p.mode }} {{ frappe.utils.fmt_money(p.amount, currency=cur) }}{% if not loop.last %}, {% endif %}{% endfor %}</div>{% endif %}
		</td>
		<td style="vertical-align:top">
			<table class="totals">
				<tr><td>{{ _("Taxable Value") }}</td><td class="r">{{ frappe.utils.fmt_money(v.net_total, currency=cur) }}</td></tr>
				{%- for t in v.taxes %}<tr><td>{{ t.description }}{% if t.rate %} @{{ t.rate | round(2) }}%{% endif %}</td><td class="r">{{ frappe.utils.fmt_money(t.amount, currency=cur) }}</td></tr>{% endfor %}
				{%- if v.discount %}<tr><td>{{ _("Discount") }}</td><td class="r">-{{ frappe.utils.fmt_money(v.discount, currency=cur) }}</td></tr>{% endif %}
				{%- if v.rounding %}<tr><td>{{ _("Rounding") }}</td><td class="r">{{ frappe.utils.fmt_money(v.rounding, currency=cur) }}</td></tr>{% endif %}
				<tr class="grand"><td>{{ _("Grand Total") }}</td><td class="r">{{ frappe.utils.fmt_money(v.grand_total, currency=cur) }}</td></tr>
				{%- if v.outstanding and not doc.is_pos %}<tr><td>{{ _("Balance Due") }}</td><td class="r">{{ frappe.utils.fmt_money(v.outstanding, currency=cur) }}</td></tr>{% endif %}
			</table>
		</td>
	</tr></table>
	{%- if doc.terms %}<div style="margin-top:8px" class="muted"><b>{{ _("Terms") }}</b><br>{{ doc.terms }}</div>{% endif %}
	<table style="margin-top:28px"><tr>
		<td class="muted">{{ _("This is a computer generated invoice.") }}</td>
		<td class="r">{{ _("For") }} <b>{{ v.company.name }}</b><br><br><br>{{ _("Authorised Signatory") }}</td>
	</tr></table>
</div>
